#include <iostream>
#include <vector>

int main() {
    std::vector<int> datos{2, 7, 4, 1};
    int total = 0;
    std::vector<int> elegidos;
    for (int valor : datos) {
        total += valor;
        if (valor >= 4) {
            elegidos.push_back(valor);
        }
    }
    std::cout << "Total: " << total << "\n";
    std::cout << "Elegidos: " << elegidos.size() << "\nValores:";
    for (int valor : elegidos) {
        std::cout << valor << ";";
    }
    return 0;
}

